CREATE TABLE pa_plain(a integer);
CREATE TABLE pa_tree(a integer) PARTITION BY RANGE (a);
CREATE TABLE pa_branch PARTITION OF pa_tree FOR VALUES FROM (0) TO (10) PARTITION BY RANGE (a);
CREATE TABLE pa_leaf PARTITION OF pa_branch FOR VALUES FROM (0) TO (5);
SELECT pg_partition_ancestors('pa_plain');
SELECT pg_partition_root('pa_plain') IS NULL;
SELECT pg_partition_ancestors('pa_leaf'), pg_partition_root('pa_leaf');
SELECT relid, pg_typeof(relid) FROM pg_partition_ancestors('pa_branch'::regclass);
SELECT conname FROM pg_constraint WHERE confrelid IN (SELECT pg_catalog.pg_partition_ancestors('pa_leaf') UNION ALL VALUES ('pa_leaf'::pg_catalog.regclass));
SELECT * FROM pg_partition_ancestors(0);
CREATE TABLE pa_twig PARTITION OF pa_tree FOR VALUES FROM (10) TO (20);
SELECT relid, parentrelid, isleaf, level FROM pg_partition_tree('pa_tree');
SELECT pg_partition_tree('pa_branch');
SELECT count(*) FROM pg_partition_tree('pa_plain');
SELECT * FROM pg_partition_tree(0);
DROP TABLE pa_tree, pa_plain;
-- Without ORDER BY, a scan or write of a partitioned table reads its
-- partitions in bound order and an inheritance tree level by level.
CREATE TABLE po_range(id integer, note text) PARTITION BY RANGE (id);
CREATE TABLE po_range_default PARTITION OF po_range DEFAULT;
CREATE TABLE po_range_high PARTITION OF po_range FOR VALUES FROM (200) TO (300);
CREATE TABLE po_range_mid PARTITION OF po_range FOR VALUES FROM (100) TO (200) PARTITION BY LIST (note);
CREATE TABLE po_range_mid_b PARTITION OF po_range_mid FOR VALUES IN ('b');
CREATE TABLE po_range_mid_null PARTITION OF po_range_mid FOR VALUES IN (NULL);
CREATE TABLE po_range_mid_a PARTITION OF po_range_mid FOR VALUES IN ('z', 'a');
CREATE TABLE po_range_low PARTITION OF po_range FOR VALUES FROM (0) TO (100);
INSERT INTO po_range VALUES (900, 'd'), (250, 'h'), (150, 'b'), (151, 'a'), (152, NULL), (50, 'l');
SELECT id, note FROM po_range;
UPDATE po_range SET note = note || '+' RETURNING id, note;
DELETE FROM po_range WHERE id > 100 RETURNING id;
CREATE TABLE po_hash(id integer) PARTITION BY HASH (id);
CREATE TABLE po_hash_2 PARTITION OF po_hash FOR VALUES WITH (MODULUS 2, REMAINDER 1);
CREATE TABLE po_hash_1 PARTITION OF po_hash FOR VALUES WITH (MODULUS 4, REMAINDER 2);
CREATE TABLE po_hash_0 PARTITION OF po_hash FOR VALUES WITH (MODULUS 4, REMAINDER 0);
INSERT INTO po_hash SELECT generate_series(1, 8);
SELECT id FROM po_hash;
CREATE TABLE po_parent(id integer);
CREATE TABLE po_child_a(extra integer) INHERITS (po_parent);
CREATE TABLE po_child_b() INHERITS (po_parent);
CREATE TABLE po_grandchild() INHERITS (po_child_a);
INSERT INTO po_grandchild VALUES (1, 0);
INSERT INTO po_child_b VALUES (2);
INSERT INTO po_child_a VALUES (3, 0);
INSERT INTO po_parent VALUES (4);
SELECT id FROM po_parent;
UPDATE po_parent SET id = id * 10 RETURNING id;
DROP TABLE po_range, po_hash, po_parent CASCADE;
